<?php
require __DIR__.'/bootstrap.php';

$error='';
$identity=udaan_player_session_identity();
$player=$identity?$store->getPlayer($identity):null;

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!global_csrf_matches($_POST['csrf']??null))$error='Session expired. Refresh and try again.';
    else{
        $rate=$store->rateLimit('player-save',request_fingerprint('player-save'),20,600);
        if(!$rate['allowed']){rate_limit_retry_header($rate);http_response_code(429);$error='Too many profile updates. Please try again shortly.';}
        else{
            $deviceInstallId=strtolower(trim((string)($_POST['device_install_id']??'')));
            $deviceHash=device_identity($deviceInstallId);
            if($deviceHash==='')$error='This browser could not provide a valid secure device identity. Refresh and try again.';
            else{
                $identity=udaan_player_identity_from_device_hash($deviceHash);
                $existing=$store->getPlayer($identity);$created=!is_array($existing);
                if(!$existing)$existing=udaan_player_default($identity);
                try{
                    $player=udaan_player_normalize($_POST,$existing);
                    $store->putPlayer($identity,$player);
                    udaan_player_session_set($identity);
                    $store->appendPlayerEvent(udaan_player_event($created?'player.created':'player.updated',$player,[
                        'arena'=>'core',
                        'main_goal'=>$player['main_goal'],
                        'language'=>$player['language'],
                        'arenas'=>$player['arenas'],
                        'daily_minutes'=>$player['daily_minutes'],
                    ]));
                    header('Location: '.app_url('today'));exit;
                }catch(InvalidArgumentException $e){$error=$e->getMessage();}
            }
        }
    }
}

$player=is_array($player)?$player:null;
$arenas=udaan_player_arenas();$goals=udaan_player_goals();$ages=udaan_player_age_groups();$stages=udaan_player_stages();$languages=udaan_player_languages();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $player?'Edit Player':'Create Player' ?> · Udaan</title><?=common_assets_head()?><style>
.player-wrap{max-width:1040px;margin:0 auto;padding:28px 20px 70px}.player-head{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:32px}.player-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,.72fr);gap:28px}.player-card,.player-aside{background:var(--panel,#fff);border:1px solid rgba(90,80,60,.15);border-radius:28px;padding:28px;box-shadow:0 18px 60px rgba(40,35,24,.07)}.player-card h1{font-size:clamp(36px,5vw,64px);line-height:.98;margin:8px 0 14px}.player-card .lead{max-width:680px}.player-form{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:28px}.player-form .full{grid-column:1/-1}.arena-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.arena-option{display:flex;gap:10px;align-items:center;padding:14px;border:1px solid rgba(90,80,60,.16);border-radius:16px}.arena-option input{width:auto}.privacy-note{padding:16px;border-radius:16px;background:rgba(57,113,90,.08);font-size:14px;line-height:1.5}.player-aside h2{margin-top:8px}.player-aside ul{padding-left:18px;line-height:1.7}.player-id{font-family:ui-monospace,monospace;font-size:12px;word-break:break-all}.player-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}@media(max-width:820px){.player-grid{grid-template-columns:1fr}.player-form{grid-template-columns:1fr}.player-form .full{grid-column:auto}}
</style></head><body><main class="player-wrap"><header class="player-head"><a class="brand" href="<?=h(route_url('home'))?>"><span class="brand-mark">उ</span><span>Udaan</span></a><div class="player-actions"><a class="ghost" href="<?=h(app_url('momentum'))?>">Momentum</a><a class="ghost" href="<?=h(app_url('today'))?>">Today</a><a class="ghost" href="<?=h(app_url('fit'))?>">Fit</a><a class="ghost" href="<?=h(app_url('progress'))?>">Progress</a><?=theme_toggle()?></div></header><div class="player-grid"><section class="player-card"><p class="eyebrow">UDAAN PLAYER · FOUNDATION</p><h1><?= $player?'Shape your Player profile.':'Build your Udaan Player.' ?></h1><p class="lead">One private-by-default identity for learning, fitness, focus and reflection. This foundation will power future Missions, performance history, Coach recommendations, teams and leagues.</p><?php if($error):?><p class="form-error"><?=h($error)?></p><?php endif;?><form class="player-form" method="post" data-progress-submit data-progress-label="Saving your Udaan Player"><input type="hidden" name="csrf" value="<?=h(global_csrf())?>"><input type="hidden" name="device_install_id" id="device-install-id" value=""><div class="field"><label>NICKNAME</label><input name="nickname" maxlength="24" required value="<?=h((string)($player['nickname']??''))?>" placeholder="e.g. Aarav"></div><div class="field"><label>PREFERRED LANGUAGE</label><select name="language"><?php foreach($languages as$key=>$label):?><option value="<?=h($key)?>" <?=($player['language']??'en')===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></div><div class="field"><label>AGE GROUP</label><select name="age_group" required><option value="">Choose</option><?php foreach($ages as$key=>$label):?><option value="<?=h($key)?>" <?=($player['age_group']??'')===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></div><div class="field"><label>LEARNING STAGE</label><select name="stage" required><option value="">Choose</option><?php foreach($stages as$key=>$label):?><option value="<?=h($key)?>" <?=($player['stage']??'')===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></div><div class="field"><label>MAIN GOAL</label><select name="main_goal"><?php foreach($goals as$key=>$label):?><option value="<?=h($key)?>" <?=($player['main_goal']??'general')===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></div><div class="field"><label>DAILY TIME</label><select name="daily_minutes"><?php foreach([15,20,30,45,60,90,120,180] as$n):?><option value="<?=$n?>" <?=((int)($player['daily_minutes']??30)===$n)?'selected':''?>><?=$n?> minutes</option><?php endforeach;?></select></div><div class="field full"><label>EXAM / TARGET (OPTIONAL)</label><input name="exam_target" maxlength="80" value="<?=h((string)($player['exam_target']??''))?>" placeholder="e.g. NEET 2027, Class X boards, UPSC 2028"></div><div class="full"><label>ARENAS YOU WANT IN YOUR UDAAN</label><div class="arena-grid"><?php $selected=is_array($player['arenas']??null)?$player['arenas']:['learn'];foreach($arenas as$key=>$label):?><label class="arena-option"><input type="checkbox" name="arenas[]" value="<?=h($key)?>" <?=in_array($key,$selected,true)?'checked':''?>><span><strong><?=h($label)?></strong></span></label><?php endforeach;?></div></div><label class="arena-option full"><input type="checkbox" name="share_achievements" value="1" <?=!empty($player['privacy']['share_achievements'])?'checked':''?>><span><strong>Allow share-card generation</strong><br><small>Nothing becomes public automatically. Sharing remains an explicit action.</small></span></label><div class="privacy-note full"><strong>Private by default.</strong> Readiness, health, fitness, mindset and reflection data will remain private unless a future sharing feature asks for explicit permission. Parent/institution sharing is OFF in this foundation release.</div><div class="full"><button class="primary"><?= $player?'Save Player profile →':'Create my Udaan Player →' ?></button></div></form></section><aside class="player-aside"><p class="eyebrow">WHY THIS FOUNDATION</p><h2>One Player. Many Arenas.</h2><ul><li>Goals guide future Missions.</li><li>Language stays attached to the Player, not each page.</li><li>Arena choices allow Learn, Fit, Mind and Reflect to share one identity.</li><li>Events build a future performance history without inventing a single “student score”.</li><li>The storage layer can move to a database later without changing the product model.</li></ul><?php if($player):?><p class="eyebrow">PLAYER ID</p><p class="player-id"><?=h((string)$player['id'])?></p><a class="ghost" href="<?=h(app_url('today'))?>">Open Today →</a><?php endif;?></aside></div></main><script src="<?=h(app_url('assets/js/device-id.js?v=0.12.0'))?>" defer></script><?=common_theme_script()?></body></html>